		pass

	# --- In-memory content operations ---

	def update_content(self, new_content: str) -> None:
		"""Replace the in-memory content of the file"""
		self.content = new_content

	# --- Disk operations ---

	def sync_to_disk_sync(self, base_dir: Path) -> None:
		"""Synchronously write the current content to disk under base_dir"""
		file_path = base_dir / self.full_name
		try:
			file_path.write_text(self.content, encoding='utf-8')
