		await asyncio.to_thread(self.sync_to_disk_sync, base_dir)

	async def write(self, content: str, base_dir: Path) -> None:
		"""Replace content in memory and persist it to disk"""
		self.update_content(content)
		await self.sync_to_disk(base_dir)

	async def append(self, content: str, base_dir: Path) -> None:
		"""Append content in memory and persist it to disk"""
		self.update_content(self.content + content)
		await self.sync_to_disk(base_dir)

