	@property
	def get_size(self) -> int:
		"""File size in characters"""
		return len(self.content)

	@property
	def get_line_count(self) -> int:
		"""Number of lines in the file"""
		return len(self.content.splitlines())

	@property
	def full_name(self) -> str:
